import { createClientFromRequest } from 'npm:@base44/sdk@0.8.54';

const items = (r) => (r && r.items ? r.items : Array.isArray(r) ? r : []);

// AI Business Master — community knowledge assistant. Answers industry and
// business-education questions for community members using ONLY public,
// published community content plus general knowledge. Never accesses private
// contractor records, financial data or internal owner data. Answers are
// clearly labeled AI-generated by the caller.
export default async function(req) {
  try {
    const base44 = createClientFromRequest(req);
    const user = await base44.auth.me();
    if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 });

    const body = await req.json().catch(() => ({}));
    const question = String(body?.question || '').trim().slice(0, 2000);
    if (!question) return Response.json({ error: 'A question is required.' }, { status: 400 });

    const [posts, resources, comments] = await Promise.all([
      base44.asServiceRole.entities.CommunityPost.list({ status: 'published' }, { limit: 150, sort: '-created_date' }),
      base44.asServiceRole.entities.CommunityResource.list({ status: 'published' }, { limit: 100, sort: '-created_date' }),
      base44.asServiceRole.entities.CommunityComment.list({ status: 'published' }, { limit: 300, sort: '-created_date' }),
    ]);
    const postRows = items(posts);
    const commentRows = items(comments);
    const byPost = {};
    for (const c of commentRows) (byPost[c.post_id] = byPost[c.post_id] || []).push(String(c.body || '').slice(0, 300));

    const context = {
      library: items(resources).map((r) => ({ title: r.title, category: r.category })),
      discussions: postRows.slice(0, 80).map((p) => ({
        title: p.title,
        channel: p.channel,
        body: String(p.body || '').slice(0, 500),
        top_replies: (byPost[p.id] || []).slice(0, 3),
      })),
    };

    const ai = await base44.asServiceRole.integrations.Core.InvokeLLM({
      prompt:
        'You are the AI Business Master community assistant for a Canadian recycling and junk-removal professional community. You help members with industry questions, business terminology, general financial education and finding existing community answers.\n' +
        'STRICT RULES:\n' +
        '- You only see PUBLIC community content below. Never reference, guess or imply access to any member\'s private financial records, contracts or internal business data.\n' +
        '- When an existing community discussion or library article already answers the question, point the member to it by title.\n' +
        '- Give practical, Canada-aware general guidance. Never present estimates as confirmed results.\n' +
        '- Legal, tax, insurance and regulatory questions: give educational context only and tell the member to confirm with a qualified professional.\n' +
        '- Keep answers clear and concise (under ~350 words). Plain language; define jargon when used.\n' +
        '- If the community has no related discussion, say so and invite the member to start one (suggested channel).\n\n' +
        'PUBLIC COMMUNITY CONTENT (JSON):\n' + JSON.stringify(context) +
        '\n\nMEMBER QUESTION: ' + question,
      response_json_schema: {
        type: 'object',
        properties: {
          answer: { type: 'string' },
          related_discussions: { type: 'array', items: { type: 'string' } },
          related_resources: { type: 'array', items: { type: 'string' } },
          suggested_channel: { type: 'string' },
        },
        required: ['answer'],
      },
    });

    return Response.json({
      answer: String(ai.answer || '').slice(0, 6000),
      related_discussions: (ai.related_discussions || []).slice(0, 5),
      related_resources: (ai.related_resources || []).slice(0, 5),
      suggested_channel: ai.suggested_channel ? String(ai.suggested_channel).slice(0, 60) : null,
      ai_label: 'AI-generated answer — general guidance, not professional advice.',
      generated_at: new Date().toISOString(),
    });
  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
}